INSERT INTO "dynasties" ("id","name","alt_names","ethnicity","feudal_rank","scope","region","start_year","start_month","start_day","start_confidence","end_year","end_month","end_day","end_confidence","start_abs","end_abs","color_token","parent_id","group_id","note") VALUES ('guo-chunqiu','西虢国','["虢","虢国","南虢"]',NULL,'{"periods":[{"rank":"公","start":{"year":-1046,"month":1,"confidence":"year"},"end":{"year":-655,"month":12,"confidence":"month"}}]}','cn','east_asia',-1046,1,NULL,'year',-655,12,NULL,'month',-12540,-7837,'ochre',NULL,NULL,'周朝姬姓诸侯国，本条目聚焦西虢；其东迁后三门峡一带亦称南虢。西虢传统君主序列：虢叔 → 郭叔 → 史料缺 → 城公 → 史料缺 → 厉公 → 宣公 → 文公 → 石父 → 翰 → 忌父 → 林父 → 丑。长父之后的君主，一说为宣公，一说为文公。
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('guo-de-shu','虢德叔','guo-chunqiu','["即","德叔"]','姬','虢季',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["贵族","西虢君主身份待考"]','虢德叔，姬姓，字即，虢幽叔之子、师丞之父。即簋记其任周王宫廷近臣；活动年代有共王时期、孝王至夷王时期等说。其西虢君主身份有争议，在位起讫不详。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/虢德叔"},{"label":"虢国君主世系（主序列与待考虢季家族）","url":"https://zh.wikipedia.org/wiki/Template:虢國君主"},{"label":"西虢国（金文家族君主身份待考）","url":"https://zh.wikipedia.org/wiki/西虢国#金文中的虢国氏族"}]','德叔',NULL,'虢德叔','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('guo-gong-chou','丑','guo-chunqiu','["虢公醜","虢叔"]','姬','虢',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["君主"]','虢公丑（又作虢公醜），春秋时期西虢末代君主，生卒及父祖世系不详。前673年与郑厉公合兵平定王子颓之乱，助周惠王复位。前655年晋献公再次借道虞国灭虢，虢公丑出奔周王室京师；《左传》同段记被俘者为虞公及井伯。虢公丑此后的确切卒年不详。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/虢公丑"},{"label":"《左传·僖公五年》（晋灭虢、虢公丑奔京师）","url":"https://zh.wikisource.org/wiki/春秋左氏傳/僖公"}]',NULL,NULL,'','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('guo-gui-gong','虢宄公','guo-chunqiu','["虢宫公","师哉","宄公"]','姬','虢季',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["贵族","西虢君主身份待考"]','虢宄公，一作虢宫公，姬姓，字哉，虢季易父之子、虢幽叔之父。师哉鼎记其任周王室军职及受命为太师；主要活动于周穆王、共王时期。其西虢君主身份有争议，在位起讫不详。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/虢宄公"},{"label":"虢国君主世系（主序列与待考虢季家族）","url":"https://zh.wikipedia.org/wiki/Template:虢國君主"},{"label":"西虢国（金文家族君主身份待考）","url":"https://zh.wikipedia.org/wiki/西虢国#金文中的虢国氏族"}]','宄公,宫公',NULL,'虢宄公','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('guo-ji-yifu','挞','guo-chunqiu','["虢季易父","易父"]','姬','虢季',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["贵族","西虢君主身份待考"]','虢季易父，姬姓，名挞，字易父，西周虢季家族人物，虢宄公之父。师丞钟记其家族五代世系；其是否兼任西虢君主存在争议，在位起讫不详。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/虢季易父"},{"label":"虢国君主世系（主序列与待考虢季家族）","url":"https://zh.wikipedia.org/wiki/Template:虢國君主"},{"label":"西虢国（金文家族君主身份待考）","url":"https://zh.wikipedia.org/wiki/西虢国#金文中的虢国氏族"}]',NULL,NULL,'虢季易父','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('guo-r1','','guo-chunqiu','[]','姬','虢',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["君主"]','周文王之弟，王季之子，与虢仲同为文王卿士。“叔”是虢君之字/排行称谓，不是可确认的私名；现存可靠记载未见其私名。传统说法以其为西虢始封君；东、西虢始封君归属存在异说，具体在位起讫不详。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/虢叔"},{"label":"周朝诸侯国君主列表（西虢中间世系失考）","url":"https://zh.wikipedia.org/wiki/周朝諸侯國君主列表#西虢国"},{"label":"西虢国（金文人物、年代及世系争议）","url":"https://zh.wikipedia.org/wiki/西虢国#金文中的虢国氏族"},{"label":"虢国君主世系（主序列与待考虢季家族）","url":"https://zh.wikipedia.org/wiki/Template:虢國君主"},{"label":"周朝（共时定位采用的年表）","url":"https://zh.wikipedia.org/wiki/周朝"},{"label":"《春秋左传正义·僖公五年》（杜预注：仲、叔皆虢君字；孔颖达疏辨始封君归属无明证）","url":"https://www.zggdwx.com/zuozhuanzhengyi/12.html"}]',NULL,NULL,'虢叔','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('guo-r10','林父','guo-chunqiu','["虢仲"]','姬','虢',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["君主"]','虢公林父，姬姓虢氏，曾任周王室卿士。前707年繻葛之战率王室右军，前706、前703年奉命讨伐曲沃，前702年被迫出奔虞国，均见《左传》。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/虢公林父"}]',NULL,NULL,'','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('guo-r2','郭叔','guo-chunqiu','["虢叔"]','姬','虢',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["君主"]','郭叔（一作虢叔），西周虢国人物。《逸周书·王会》记其掌天子贡币；《虢国研究》认为其为始封君虢叔之子。具体在位起讫不详，与虢城公之间世系失考，不能确定为虢城公的直接前任。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/郭叔"},{"label":"周朝诸侯国君主列表（西虢中间世系失考）","url":"https://zh.wikipedia.org/wiki/周朝諸侯國君主列表#西虢国"},{"label":"西虢国（金文人物、年代及世系争议）","url":"https://zh.wikipedia.org/wiki/西虢国#金文中的虢国氏族"},{"label":"《逸周书·王会》（郭叔掌贡币）","url":"https://ctext.org/lost-book-of-zhou/wang-hui/zh"},{"label":"虢国君主世系（主序列与待考虢季家族）","url":"https://zh.wikipedia.org/wiki/Template:虢國君主"},{"label":"周朝（共时定位采用的年表）","url":"https://zh.wikipedia.org/wiki/周朝"}]',NULL,NULL,'郭叔','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('guo-r3','','guo-chunqiu','["虢成公"]','姬','虢',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["君主"]','虢城公，班簋铭文所见西周虢国人物。铭文记周王命毛伯接替其职务，并非国君传位记载。其所属东、西虢及活动年代存在异说，一说为周昭王、穆王时期人；具体在位起讫及直接前任失考。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/虢城公"},{"label":"周朝诸侯国君主列表（西虢中间世系失考）","url":"https://zh.wikipedia.org/wiki/周朝諸侯國君主列表#西虢国"},{"label":"西虢国（金文人物、年代及世系争议）","url":"https://zh.wikipedia.org/wiki/西虢国#金文中的虢国氏族"},{"label":"《班簋铭文》（毛伯接替虢城公职务）","url":"https://zh.wikisource.org/wiki/班簋銘文"},{"label":"虢国君主世系（主序列与待考虢季家族）","url":"https://zh.wikipedia.org/wiki/Template:虢國君主"},{"label":"周朝（共时定位采用的年表）","url":"https://zh.wikipedia.org/wiki/周朝"},{"label":"冯时《班簋铭文补释》（穆王时期）","url":"https://www.ctwx.tsinghua.edu.cn/__local/A/61/04/3B0E595B6786E89BFDFF5B51A67_192072D8_490B29.pdf?e=.pdf"}]',NULL,NULL,'城公','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('guo-r4','长父','guo-chunqiu','["虢厉公","虢仲","虢公长父"]','姬','虢',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["君主"]','虢公长父，又称虢厉公、虢仲，主要活动于周厉王时期，曾任卿士并奉命征讨淮夷。具体在位年代不详。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/虢公长父"},{"label":"河南博物院《虢硕父簠》","url":"https://www.chnmus.net/ch/collection/appraise/details.html?id=512153734134559839"}]','厉',NULL,'厉公','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('guo-r5','子白','guo-chunqiu','["虢季子白","虢季","虢宣公"]','姬','虢',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["君主"]','虢宣公，亦称虢季子白，周宣王时期率军攻猃狁，相关事迹见虢季子白盘铭文。虢公长父之后的继承顺序有宣公、文公两说。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/虢宣公"},{"label":"虢国君主世系（宣公、文公顺序异说）","url":"https://zh.wikipedia.org/wiki/Template:虢國君主"}]','宣',NULL,'宣公','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('guo-r6','季','guo-chunqiu','["虢季","虢文公"]','姬','虢',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["君主"]','虢文公，周宣王时期任卿士，曾谏宣王举行籍田礼，事见《国语·周语上》。具体在位年代不详；虢公长父之后的继承顺序有宣公、文公两说。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/虢文公"},{"label":"虢国君主世系（宣公、文公顺序异说）","url":"https://zh.wikipedia.org/wiki/Template:虢國君主"}]','文',NULL,'文公','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('guo-r7','鼓','guo-chunqiu','["虢石甫","虢公鼓","虢硕父"]','姬','虢',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["君主"]','虢石父，又称虢公鼓，主要活动于周幽王时期，前775年灭焦为一说。西周灭亡后其世系及去向不详。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/虢石父"}]',NULL,NULL,'虢石父','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('guo-r8','翰','guo-chunqiu','["虢公翰"]','姬','虢',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["君主"]','虢公翰，西周末至东周初的虢国君主，一说为虢石父之子。具体在位年代及世系关系不详。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/虢公翰"}]',NULL,NULL,'','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('guo-r9','忌父','guo-chunqiu','["虢公忌父"]','姬','虢',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["君主"]','虢公忌父，周平王晚年受用为王室卿士，前720年周平王有意分郑伯政于忌父，前715年任右卿士，见《左传·隐公八年》及相关年表。即位年不详。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/虢公忌父"}]',NULL,NULL,'','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('guo-shi-cheng','师丞','guo-chunqiu','["虢公师丞"]','姬','虢季',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["贵族","西虢君主身份待考"]','师丞，姬姓，字丞，虢德叔之子。师丞钟列叙虢季易父、宄公、幽叔、德叔至师丞五代世系。其活动年代及西虢君主身份存在争议，与城公、厉公主序列的衔接未能确定，在位起讫不详。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/师丞"},{"label":"虢国君主世系（主序列与待考虢季家族）","url":"https://zh.wikipedia.org/wiki/Template:虢國君主"},{"label":"西虢国（金文家族君主身份待考）","url":"https://zh.wikipedia.org/wiki/西虢国#金文中的虢国氏族"}]',NULL,NULL,'师丞','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('guo-you-shu','虢幽叔','guo-chunqiu','["师望","幽叔"]','姬','虢季',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["贵族","西虢君主身份待考"]','虢幽叔，姬姓，字望，虢宄公之子、虢德叔之父。师望鼎记其承袭父亲的太师职务并受周王赏赐；活动年代有共王时期、懿王至孝王时期等说。其西虢君主身份有争议，在位起讫不详。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/虢幽叔"},{"label":"虢国君主世系（主序列与待考虢季家族）","url":"https://zh.wikipedia.org/wiki/Template:虢國君主"},{"label":"西虢国（金文家族君主身份待考）","url":"https://zh.wikipedia.org/wiki/西虢国#金文中的虢国氏族"}]','幽叔',NULL,'虢幽叔','[]');
